        begin
            test_num = 2;
            $display("Testcase %0d: Load Alternating Pattern 8'h55", test_num);
            reset_dut();
            data_in = 8'h55;
            @(posedge clk);
            @(negedge clk);
            #2;
            #1;

            check_outputs(8'h55);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Testcase %0d: Load Alternating Pattern 8'hAA", test_num);
