            data_in = 8'h12;
            @(posedge clk);


            data_in = 8'h34;
            @(negedge clk);

            @(posedge clk);
            @(negedge clk);
            #2;
            #1;

            check_outputs(8'h34);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            $display("Testcase %0d: Persistence check", test_num);
