module xor_gate(input a, b, control, output reg out);
  wire xor_result;
  assign xor_result = a ^ b;

  always @(*) begin
    if (control == 1'b1) begin
      out <= 1'bz;
    end else begin
      out <= xor_result;
    end
  end
endmodule

